"use client";

import Script from "next/script";
import { useCallback, useEffect, useRef, useState } from "react";
import { getTurnstileSiteKey } from "@/lib/public-config";

type TurnstileApi = {
  render: (element: HTMLElement, options: { sitekey: string; action: string; callback: (token: string) => void; "expired-callback": () => void; "error-callback": () => void; }) => string;
  remove: (id: string) => void;
};

function api() { return (window as unknown as { turnstile?: TurnstileApi }).turnstile; }

export function TurnstileWidget({ action, onToken, resetKey = 0 }: { action: string; onToken: (token: string | null) => void; resetKey?: number; }) {
  const sitekey = getTurnstileSiteKey();
  const testBypass = process.env.NODE_ENV !== "production" && process.env.NEXT_PUBLIC_TURNSTILE_TEST_BYPASS === "1";
  const elementRef = useRef<HTMLDivElement | null>(null);
  const widgetRef = useRef<string | null>(null);
  const [ready, setReady] = useState(false);

  const renderWidget = useCallback(() => {
    if (testBypass) { onToken("dev-bypass"); return; }
    if (!sitekey || !elementRef.current || !api()) return;
    if (widgetRef.current) api()?.remove(widgetRef.current);
    onToken(null);
    widgetRef.current = api()!.render(elementRef.current, {
      sitekey,
      action,
      callback: token => onToken(token),
      "expired-callback": () => onToken(null),
      "error-callback": () => onToken(null),
    });
  }, [action, onToken, sitekey, testBypass]);

  useEffect(() => { if (ready || testBypass) renderWidget(); return () => { if (widgetRef.current) api()?.remove(widgetRef.current); widgetRef.current = null; }; }, [ready, resetKey, renderWidget, testBypass]);

  if (testBypass) return <span className="privacy-note" data-testid="turnstile-bypass">Challenge bypass enabled for local tests.</span>;
  if (!sitekey) return <span className="privacy-note">Bot challenge is not configured.</span>;
  return <><Script src="https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit" strategy="afterInteractive" onReady={() => setReady(true)} /><div ref={elementRef} data-testid={`turnstile-${action}`} /></>;
}

import { timingSafeEqual } from "node:crypto";
import { expireStaleReservations, reconcileDeletedSubjects } from "@/lib/billing/server";
import { apiError, apiOk, requestContext } from "@/lib/server/api";
import { logEvent } from "@/lib/server/observability";

export const runtime="nodejs";
function authorized(request:Request){const secret=process.env.CRON_SECRET;const supplied=request.headers.get("authorization")?.replace(/^Bearer\s+/iu,"")??"";if(!secret||!supplied)return false;const a=Buffer.from(secret);const b=Buffer.from(supplied);return a.length===b.length&&timingSafeEqual(a,b);}
function count(value:unknown,key:string){return value&&typeof value==="object"&&!Array.isArray(value)?Number((value as Record<string,unknown>)[key]??0):0;}
export async function GET(request:Request){
  const context=requestContext(request,"/api/internal/reconcile");
  if(!authorized(request))return apiError(context,"unauthorized","Not authorized.",401);
  try{
    const reservations=await expireStaleReservations(200);
    let deletions:unknown={finalized:0,cancelled:0};
    try{deletions=await reconcileDeletedSubjects(200);}catch{/* Phase 6 is enforced by readiness; keep stale reservation recovery independent. */}
    const expired=count(reservations,"expired");
    const finalizedDeleted=count(deletions,"finalized");
    const cancelledStaleDeletions=count(deletions,"cancelled");
    logEvent("billing_reconciliation",{requestId:context.requestId,expired,finalizedDeleted,cancelledStaleDeletions,latencyMs:Date.now()-context.startedAt});
    return apiOk(context,{reconciled:true,expired,finalizedDeleted,cancelledStaleDeletions});
  }catch{
    logEvent("reservation_reconciliation_failed",{requestId:context.requestId});
    return apiError(context,"reconciliation_failed","Reservation reconciliation failed.",503);
  }
}

import type { C2paVerificationReceipt } from "@/lib/c2pa/types";
import type { FileInspectionReceipt, FileSanitizeResult } from "./types";

export interface ExportableFileVerificationReceipt {
  version: "file-verification-v2";
  generatedAt: string;
  original: {
    sha256: string;
    inspection: FileInspectionReceipt;
    c2pa?: C2paVerificationReceipt;
  };
  sanitized?: {
    sha256: string;
    inspection: FileInspectionReceipt;
    removedFindingIds: string[];
  };
  policy: {
    rawContentStored: false;
    provenanceRemoval: false;
    provenanceBearingAssetsModifiedByDefault: false;
  };
}

export function buildVerificationReceipt(input: {
  originalHash: string;
  inspection: FileInspectionReceipt;
  c2pa?: C2paVerificationReceipt | null;
  cleaned?: FileSanitizeResult | null;
  cleanedHash?: string | null;
}): ExportableFileVerificationReceipt {
  const receipt: ExportableFileVerificationReceipt = {
    version: "file-verification-v2",
    generatedAt: new Date().toISOString(),
    original: {
      sha256: input.originalHash,
      inspection: input.inspection,
      ...(input.c2pa ? { c2pa: input.c2pa } : {}),
    },
    policy: {
      rawContentStored: false,
      provenanceRemoval: false,
      provenanceBearingAssetsModifiedByDefault: false,
    },
  };

  if (input.cleaned && input.cleanedHash) {
    receipt.sanitized = {
      sha256: input.cleanedHash,
      inspection: input.cleaned.after,
      removedFindingIds: input.cleaned.removed.map((item) => item.id),
    };
  }

  return receipt;
}

